/// <summary>
/// The extension class for Inventroy transfer order updates.
/// </summary>
[ExtensionOf(classStr(InventTransferUpd))]
final class METInventTransferUpd_Extension
{    								
}

Method.Source:
    /// <summary>
    /// Extension of insert journal line method for transfer orders.
    /// </summary>
    protected void insertJournalLines()
    {
        #OCCRetryCount
        InventTransferJourLine  inventTransferJourLine;
        InventSite inventSite;
        InventLocation inventLocation;
        METInventItemOrderSetup metInventItemOrderSetup;
        
        next insertJournalLines();

        if (inventTransferJour.UpdateType == InventTransferUpdateType::Receive)
        {        
            try
            {
                select firstonly SiteId, METAutoUpdateItemStatusUponReceipt
                    from inventSite
                    exists join inventLocation
                    where inventLocation.InventSiteId == inventSite.SiteId
                    && inventLocation.InventLocationId == inventTransferJour.InventLocationIdTo;

                if (inventSite)
                {            
                    while select inventTransferJourLine
                        join forupdate metInventItemOrderSetup
                        where inventTransferJourLine.TransferId == inventTransferJour.TransferId 
                        && inventTransferJourLine.VoucherId == inventTransferJour.VoucherId
                        && metInventItemOrderSetup.ItemId == inventTransferJourLine.ItemId
                        && metInventItemOrderSetup.SiteId == inventSite.SiteId
                    {
                        if (inventSite.METAutoUpdateItemStatusUponReceipt)
                        {
                            if (!metInventItemOrderSetup)
                            {
                                warning(strFmt("@MET:StatusDoesNotExist", inventSite.SiteId));
                            }
                            else if ((metInventItemOrderSetup.ItemStatus == METItemStatusTable::findByStatus(METItemsStatus::New).ItemStatus || metInventItemOrderSetup.ItemStatus == ''))
                            {
                                metInventItemOrderSetup.ItemStatus          = METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus;
                                metInventItemOrderSetup.PublishPriceBook    = true;
                                metInventItemOrderSetup.PublishPortal       = true;
                                metInventItemOrderSetup.PublishHost         = true;
                                metInventItemOrderSetup.update();
                                //info(strFmt("@MET:ItemSiteUpdated",metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId, metInventItemOrderSetup.ItemStatus));
                            }
                                
                            // Update child items as well.
                            METInventItemOrderSetup::updateChildItemSiteStatus(inventTransferJourLine.ItemId, inventSite.SiteId);
                            this.itemStatusToTransferDependSites(metInventItemOrderSetup, inventTransferJour.InventLocationIdTo);
                        }
                        
                        // CB232_AutoSettingItemStockStatus.
                        // Resets item stock status from LTNA to blank.
                        METInventItemOrderSetup::resetItemStockLTNAStatus(inventTransferJourLine.ItemId, inventSite.SiteId);
                    }
                }
            }
            catch (Exception::Deadlock)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::Deadlock;
                }
                else
                {
                    retry;
                }
            }
            catch (Exception::UpdateConflict)
            {
                if (appl.ttsLevel() == 0)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        throw Exception::UpdateConflictNotRecovered;
                    }
                    else
                    {
                        retry;
                    }
                }
                else
                {
                    throw Exception::UpdateConflict;
                }
            }
            catch
            {
                throw error("@MET:UnhandledError");
            }
        }
    }

    /// <summary>
    /// Item Status to Transfer sites
    /// </summary>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup</param>
    public void itemStatusToTransferDependSites(METInventItemOrderSetup _metInventItemOrderSetup, InventLocationId _inventLocationIdFromTO)
    {
        METReqItemTableInventDimView metReqItemTableInventDimView;
        ReqItemTable    reqItemTable;
        InventDim       inventDim;
        InventLocation              inventLocation;
        METInventItemOrderSetup metInventItemOrderSetupSupplySite;
        InventParameters inventParameters = InventParameters::find();
        METItemStatusWarehouses metItemStatusWarehouses;
                
        while select ItemId, CovInventDimId, ReqPOType, InventLocationIdReqMain, VendId, MainWarehouseInventSiteId, VendGroup
            from metReqItemTableInventDimView
            where metReqItemTableInventDimView.ItemId == _metInventItemOrderSetup.ItemId  
                && metReqItemTableInventDimView.InventSiteId == _metInventItemOrderSetup.SiteId
            notexists join metItemStatusWarehouses
                where metItemStatusWarehouses.InventLocationId == metReqItemTableInventDimView.InventLocationId
        {
            if (metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer)
            {
                select firstonly InventSiteId from inventLocation
                            where inventLocation.InventLocationId == reqItemTable.InventLocationIdReqMain;

                if(inventLocation && inventLocation.InventSiteId != _metInventItemOrderSetup.SiteId)
                {
                    select firstonly metInventItemOrderSetupSupplySite
                        where metInventItemOrderSetupSupplySite.ItemId      == _metInventItemOrderSetup.ItemId  &&
                        metInventItemOrderSetupSupplySite.SiteId   == inventLocation.InventSiteId;
                        
                    if(metInventItemOrderSetupSupplySite)
                    {
                        this.updateStatusToActive(metInventItemOrderSetupSupplySite);
                        METInventItemOrderSetup::updateChildItemSiteStatus(_metInventItemOrderSetup.ItemId, inventLocation.InventSiteId);
                    }
                }
            }
            else if (metReqItemTableInventDimView.ReqPOType == ReqPOType::Purch
                && metReqItemTableInventDimView.METInterCompanySourced == NoYes::No)
            {
                //continue;
                //Commented for upcoming feature
            }
        }
        if (_inventLocationIdFromTO)// Intercompany case - Check for warehouse value in other legal entity
        {
            InventLocation inventLocationNDC;

            InventLocationId warehouse = _inventLocationIdFromTO;
            container warehouseCon;

            if (InventLocation::find(warehouse).METNDCWarehouse)
            {
                while select InventLocationId from inventLocationNDC
                    where inventLocationNDC.METNDCWarehouse == NoYes::Yes
                {
                    warehouseCon += inventLocationNDC.InventLocationId;
                }
            }
            else
            {
                warehouseCon += warehouse;
            }
                
            changecompany (inventParameters.METInterCompanyPurchaseLegalEntity)
            {
                //ReqItemTable reqItemTableIntComp;
                METReqItemTableInventDimView metReqItemTableInventDimViewIntCom;
                METItemStatusWarehouses metItemStatusWarehousesIntCom;

                while select ItemId,CovInventDimId,ReqPOType,InventLocationIdReqMain, VendId, VendIntercompanyWarehouse
                    from metReqItemTableInventDimViewIntCom
                    where metReqItemTableInventDimViewIntCom.ItemId == _metInventItemOrderSetup.ItemId
                    && metReqItemTableInventDimViewIntCom.ReqPOType == ReqPOType::Purch
                    && metReqItemTableInventDimViewIntCom.METInterCompanySourced == NoYes::Yes
                notexists join metItemStatusWarehousesIntCom
                    where metItemStatusWarehousesIntCom.InventLocationId == metReqItemTableInventDimViewIntCom.InventLocationId
                {                    
                    if (conFind(warehouseCon, metReqItemTableInventDimViewIntCom.VendIntercompanyWarehouse))
                    {
                        METInventItemOrderSetup metInventItemOrderSetupIntComp = METInventItemOrderSetup::findByItemAndSite(metReqItemTableInventDimViewIntCom.ItemId, InventDim::find(metReqItemTableInventDimViewIntCom.CovInventDimId).InventSiteId);
                        this.updateStatusToActive(metInventItemOrderSetupIntComp);
                        METInventItemOrderSetup::updateChildItemSiteStatus(metInventItemOrderSetupIntComp.ItemId, metInventItemOrderSetupIntComp.SiteId);
                    }                                         
                }
            }
        }        
    }

/// <summary>
/// Update Status
/// </summary>
/// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup table</param>
public void updateStatusToActive(METInventItemOrderSetup _metInventItemOrderSetup)
{
    if(_metInventItemOrderSetup)
    {
        _metInventItemOrderSetup.selectForUpdate(true);
        _metInventItemOrderSetup.ItemStatus = METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus;
        _metInventItemOrderSetup.PublishPriceBook = NoYes::Yes;
        _metInventItemOrderSetup.PublishPortal = NoYes::Yes;
        _metInventItemOrderSetup.PublishHost = NoYes::Yes;
        _metInventItemOrderSetup.update();
        //info(strFmt("@MET:ItemSiteUpdated",_metInventItemOrderSetup.ItemId, _metInventItemOrderSetup.SiteId, _metInventItemOrderSetup.ItemStatus));
    }
}
